-- =============================================================
-- Base: defensa_fadena
-- =============================================================

SET NAMES utf8mb4;
SET @OLD_SQL_MODE=@@SQL_MODE;
SET SQL_MODE='NO_AUTO_VALUE_ON_ZERO';
SET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS;
SET FOREIGN_KEY_CHECKS=0;

DROP DATABASE IF EXISTS `defensa_fadena`;
CREATE DATABASE `defensa_fadena` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `defensa_fadena`;

DROP TABLE IF EXISTS `resumen_diario`;
DROP TABLE IF EXISTS `incidentes`;
DROP TABLE IF EXISTS `fuentes`;
DROP TABLE IF EXISTS `estados`;
DROP TABLE IF EXISTS `sistemas`;
DROP TABLE IF EXISTS `tipos_equipo`;
DROP TABLE IF EXISTS `paises`;

-- -------------------------------------------------------------
-- Tabla `paises`
-- -------------------------------------------------------------
CREATE TABLE `paises` (
  `id_pais` INT NOT NULL AUTO_INCREMENT,
  `nombre` VARCHAR(50) NOT NULL,
  `continente` VARCHAR(50) NULL,
  `bloque_alianza` VARCHAR(50) NULL,
  `poblacion` INT NULL,
  `pib_millones_usd` INT NULL,
  `defensa_millones_usd` INT NULL,
  PRIMARY KEY (`id_pais`),
  UNIQUE KEY `uq_paises_nombre` (`nombre`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Tabla `tipos_equipo`
-- -------------------------------------------------------------
CREATE TABLE `tipos_equipo` (
  `id_tipo` INT NOT NULL AUTO_INCREMENT,
  `nombre` VARCHAR(191) NOT NULL,
  PRIMARY KEY (`id_tipo`),
  UNIQUE KEY `uq_tipos_equipo_nombre` (`nombre`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Tabla `sistemas`
-- -------------------------------------------------------------
CREATE TABLE `sistemas` (
  `id_sistema` INT NOT NULL AUTO_INCREMENT,
  `nombre` VARCHAR(191) NOT NULL,
  `id_tipo` INT NOT NULL,
  PRIMARY KEY (`id_sistema`),
  UNIQUE KEY `uq_sistemas_nombre` (`nombre`),
  KEY `idx_sistemas_tipo` (`id_tipo`),
  CONSTRAINT `fk_sistemas_tipo`
    FOREIGN KEY (`id_tipo`) REFERENCES `tipos_equipo` (`id_tipo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Tabla `estados`
-- -------------------------------------------------------------
CREATE TABLE `estados` (
  `id_estado` INT NOT NULL AUTO_INCREMENT,
  `codigo` VARCHAR(20) NOT NULL,
  `nombre` VARCHAR(20) NOT NULL,
  PRIMARY KEY (`id_estado`),
  UNIQUE KEY `uq_estados_codigo` (`codigo`),
  UNIQUE KEY `uq_estados_nombre` (`nombre`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Tabla `fuentes`
-- -------------------------------------------------------------
CREATE TABLE `fuentes` (
  `id_fuente` INT NOT NULL AUTO_INCREMENT,
  `dominio` VARCHAR(50) NOT NULL,
  PRIMARY KEY (`id_fuente`),
  UNIQUE KEY `uq_fuentes_dominio` (`dominio`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Tabla `incidentes`
-- -------------------------------------------------------------
CREATE TABLE `incidentes` (
  `id_incidente` INT NOT NULL AUTO_INCREMENT,
  `id_sistema` INT NOT NULL,
  `id_pais_operador` INT NOT NULL,
  `id_pais_origen` INT NULL,
  `id_estado` INT NOT NULL,
  `id_fuente` INT NULL,
  `fecha` DATE NOT NULL,
  `url` VARCHAR(255) NULL,
  `oryx_sys_id` INT NULL,
  `oryx_image_id` INT NULL,
  `oryx_status_id` INT NULL,
  `oryx_mat_id` VARCHAR(50) NULL,
  PRIMARY KEY (`id_incidente`),
  UNIQUE KEY `uq_incidentes_oryx_mat_id` (`oryx_mat_id`),
  KEY `idx_incidentes_sistema` (`id_sistema`),
  KEY `idx_incidentes_origen` (`id_pais_origen`),
  KEY `idx_incidentes_operador` (`id_pais_operador`),
  KEY `idx_incidentes_fecha` (`fecha`),
  KEY `idx_incidentes_estado` (`id_estado`),
  KEY `idx_incidentes_fuente` (`id_fuente`),
  CONSTRAINT `fk_incidentes_sistema`
    FOREIGN KEY (`id_sistema`) REFERENCES `sistemas` (`id_sistema`),
  CONSTRAINT `fk_incidentes_operador`
    FOREIGN KEY (`id_pais_operador`) REFERENCES `paises` (`id_pais`),
  CONSTRAINT `fk_incidentes_origen`
    FOREIGN KEY (`id_pais_origen`) REFERENCES `paises` (`id_pais`),
  CONSTRAINT `fk_incidentes_estado`
    FOREIGN KEY (`id_estado`) REFERENCES `estados` (`id_estado`),
  CONSTRAINT `fk_incidentes_fuente`
    FOREIGN KEY (`id_fuente`) REFERENCES `fuentes` (`id_fuente`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Tabla `resumen_diario`
-- -------------------------------------------------------------
CREATE TABLE `resumen_diario` (
  `id_resumen` INT NOT NULL AUTO_INCREMENT,
  `id_pais` INT NOT NULL,
  `id_tipo` INT NOT NULL,
  `fecha` DATE NOT NULL,
  `destruidos` INT NOT NULL,
  `abandonados` INT NOT NULL,
  `capturados` INT NOT NULL,
  `danados` INT NOT NULL,
  `total` INT NOT NULL,
  `var_destruidos` INT NOT NULL,
  `var_abandonados` INT NOT NULL,
  `var_capturados` INT NOT NULL,
  `var_danados` INT NOT NULL,
  `var_total` INT NOT NULL,
  PRIMARY KEY (`id_resumen`),
  KEY `idx_resumen_pais_tipo` (`id_pais`, `id_tipo`),
  KEY `idx_resumen_fecha` (`fecha`),
  CONSTRAINT `fk_resumen_pais`
    FOREIGN KEY (`id_pais`) REFERENCES `paises` (`id_pais`),
  CONSTRAINT `fk_resumen_tipo`
    FOREIGN KEY (`id_tipo`) REFERENCES `tipos_equipo` (`id_tipo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

